method next_smallest(lst: seq<int>) returns (result: ?)
    requires |lst| > 0 // The list must contain at least one element to find the second smallest
    ensures result == (if |lst| < 2 then None else (MinDistinct(lst, 2)))
    // Helper function to find the second distinct minimum element
    // If there are less than 2 distinct elements, return None

method MinDistinct(lst: seq<int>, n: int) returns (min: int?)
    requires |lst| > 0 && n > 0
    ensures min == None || (min is int && IsNthDistinct(lst, min, n))
    // This method finds the n-th distinct minimum element in the list
    // It returns None if there are fewer than n distinct elements

method IsNthDistinct(lst: seq<int>, x: int, n: int) returns (b: bool)
    requires |lst| > 0 && n > 0
    ensures b == (CountDistinctLessThan(lst, x) == n - 1)
    // This method checks if x is the n-th distinct minimum by counting elements less than x

method CountDistinctLessThan(lst: seq<int>, x: int) returns (count: int)
    requires |lst| > 0
    ensures count >= 0
    // Counts the number of distinct elements in lst that are less than x
